octo.registerCommand("broken-links", "Find broken [[wikilinks]]", function (t) {
  var text = String(t);
  var titles = octo.notes.titles();
  var known = {};
  for (var i = 0; i < titles.length; i++) {
    var full = String(titles[i]);
    known[full.toLowerCase()] = true;
    var parts = full.split("__");
    known[parts[parts.length - 1].toLowerCase()] = true;
  }
  var re = /\[\[([^\]]+)\]\]/g, m, seen = {}, missing = [];
  while ((m = re.exec(text)) !== null) {
    var target = m[1].split("|")[0].split("#")[0].replace(/^\s+|\s+$/g, "");
    if (!target) continue;
    var key = target.toLowerCase();
    if (seen[key]) continue;
    seen[key] = true;
    if (!known[key]) missing.push(target);
  }
  if (missing.length === 0) return text;
  var out = ["> [!warning] Broken links",
             "> " + missing.length + " link" + (missing.length === 1 ? "" : "s") +
             " point at a note that does not exist yet:"];
  for (var j = 0; j < missing.length; j++) out.push("> - " + missing[j]);
  return out.join("\n") + "\n\n" + text;
});
